import{_ as t,o as a,c as o,aw as l}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Контекст","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react-api/react/createContext.md","filePath":"wiki/dev-commit/framework-react/react-api/react/createContext.md"}'),s={name:"wiki/dev-commit/framework-react/react-api/react/createContext.md"};function n(r,e,c,i,p,d){return a(),o("div",null,[...e[0]||(e[0]=[l(`<h1 id="контекст" tabindex="-1">Контекст <a class="header-anchor" href="#контекст" aria-label="Permalink to &quot;Контекст&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Контекст</strong> - позволяет передавать данные через дерево компонентов без необходимости передавать пропсы на промежуточных уровнях</li></ul></div><ul><li>Контекст разработан для передачи данных, которые можно назвать «глобальными» для всего дерева React-компонентов</li><li>В типичном React-приложении данные передаются сверху вниз (от родителя к дочернему компоненту) с помощью пропсов. Однако, этот способ может быть чересчур громоздким для некоторых типов пропсов (например, выбранный язык, UI-тема), которые необходимо передавать во многие компоненты в приложении. Контекст предоставляет способ делиться такими данными между компонентами без необходимости явно передавать пропсы через каждый уровень дерева</li><li>Усложняет переиспользование компонентов</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><h3 id="_1-react-createcontext" tabindex="-1">1. React.createContext() <a class="header-anchor" href="#_1-react-createcontext" aria-label="Permalink to &quot;1. React.createContext()&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>React.createContext(defaultValue)</code></strong> - создание объекта Context. Когда React рендерит компонент, который подписан на этот объект, React получит текущее значение контекста из ближайшего подходящего <em>Provider</em> выше в дереве компонентов</p><blockquote><ul><li><code>defaultValue</code> - аргумент используется только в том случае, если для компонента нет подходящего Provider выше в дереве. Если передать undefined как значение Provider, компоненты, использующие этот контекст, не будут использовать defaultValue</li><li><em>return</em> - Объект Context</li></ul></blockquote></div><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> MyContext</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> React.</span><span style="color:#4078F2;">createContext</span><span style="color:#383A42;">(defaultValue);</span></span></code></pre></div><h3 id="_2-context-provider-в-jsx" tabindex="-1">2. Context.Provider (в JSX) <a class="header-anchor" href="#_2-context-provider-в-jsx" aria-label="Permalink to &quot;2. Context.Provider (в JSX)&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>&lt;MyContext.Provider value={}&gt;</code></strong> - Компонент используется для передачи текущего значения по дереву. Любой дочерний компонент может использовать этот контекст</p><blockquote><ul><li><code>MyContext</code> - объект Context</li><li><em>return</em> - некоторое значение</li></ul></blockquote></div><ul><li>Один Provider может быть связан с несколькими компонентами, потребляющими контекст. Так же Provider компоненты могут быть вложены друг в друга, переопределяя значение контекста глубже в дереве</li><li>Все потребители, которые являются потомками Provider, будут повторно рендериться, как только проп value у Provider изменится. Потребитель перерендерится при изменении контекста, даже если его родитель, не использующий данный контекст, блокирует повторные рендеры с помощью shouldComponentUpdate</li><li><code>value</code> - значение контекста. Проп value будут передан во все компоненты, использующие этот контекст и являющиеся потомками этого Provider компонента</li></ul><h3 id="_3-context-consumer" tabindex="-1">3. Context.Consumer <a class="header-anchor" href="#_3-context-consumer" aria-label="Permalink to &quot;3. Context.Consumer&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>&lt;MyContext. Consumer&gt;</code></strong> - React-компонент, который подписывается на изменения контекста. В свою очередь, это позволяет вам подписаться на контекст в функциональном компоненте</p></div><ul><li>Consumer принимает функцию в качестве дочернего компонента. Эта функция принимает текущее значение контекста и возвращает React-компонент. Передаваемый аргумент value будет равен ближайшему (вверх по дереву) значению этого контекста, а именно пропу value Provider компонента. Если такого Provider компонента не существует, аргумент value будет равен значению defaultValue, которое было передано в createContext()</li></ul><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#C18401;">MyContext.Consumer</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#CA1243;">  {</span><span style="color:#383A42;">value </span><span style="color:#A626A4;">=&gt;</span><span style="color:#A0A1A7;font-style:italic;"> /* отрендерить что-то, используя значение контекста */</span><span style="color:#CA1243;">}</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#C18401;">MyContext.Consumer</span><span style="color:#383A42;">&gt;</span></span></code></pre></div>`,14)])])}const v=t(s,[["render",n]]);export{m as __pageData,v as default};
